  void PotentialChanged(object sender,DataGridViewCellEventArgs e){if(loading||e.RowIndex<0)return;var row=potentials.Rows[e.RowIndex];if(row.IsNewRow)return;string slot=Cell(row,"slot");if(e.ColumnIndex==potentials.Columns["slot"].Index){loading=true;SetNameCell(row,slot,"",false);ClearPotentialDetails(row);loading=false;}if(e.ColumnIndex==potentials.Columns["name"].Index){var option=EditorTemplate.FixedOption(slot,Cell(row,"name"));if(option!=null){loading=true;ApplyOption(row,slot,option);loading=false;}}GridChanged();}
  void ApplyOption(DataGridViewRow row,string slot,RolePotentialOption option){var record=row.Tag as PotentialRecord??new PotentialRecord();record.activation="자동";record.uses=option.name=="베테랑"?"1/시":"";row.Tag=record;string condition,result;PotentialLibrary.Split(option.effect,out condition,out result);row.Cells["trigger"].Value=condition;row.Cells["effect"].Value=result;row.Cells["raw"].Value=option.effect;if(slot=="역할")SetLinkedAdjunct(option);}
  void ClearPotentialDetails(DataGridViewRow row){foreach(string name in new[]{"trigger","effect","raw"})row.Cells[name].Value="";var record=row.Tag as PotentialRecord;if(record!=null){record.activation="";record.uses="";record.targetType="";}}
  void SetNameCell(DataGridViewRow row,string slot,string value,bool preserveLegacy){var options=EditorTemplate.FixedOptions(slot);if(options!=null){var cell=new DataGridViewComboBoxCell{FlatStyle=FlatStyle.Flat,DisplayStyle=DataGridViewComboBoxDisplayStyle.DropDownButton};cell.Items.Add("");foreach(var option in options)cell.Items.Add(option.name);bool known=options.Any(x=>x.name==value);if(preserveLegacy&&value.Length>0&&!known)cell.Items.Add(value);row.Cells["name"]=cell;cell.Value=known||preserveLegacy?value:"";}else{var cell=new DataGridViewTextBoxCell();row.Cells["name"]=cell;cell.Value=value;}}
  void SetLinkedAdjunct(RolePotentialOption role){string adjunctTrigger,adjunctEffect;PotentialLibrary.Split(role.adjunctEffect,out adjunctTrigger,out adjunctEffect);DataGridViewRow target=potentials.Rows.Cast<DataGridViewRow>().FirstOrDefault(x=>!x.IsNewRow&&Cell(x,"slot")=="부수");if(role.adjunct.Length==0){if(target!=null&&EditorTemplate.RolePotentials.Any(x=>x.adjunct.Length>0&&x.adjunct==Cell(target,"name"))){foreach(string name in new[]{"name","trigger","effect","raw"})target.Cells[name].Value="";target.Tag=new PotentialRecord();}return;}if(target==null){int index=potentials.Rows.Add(false,"부수",role.adjunct,adjunctTrigger,adjunctEffect,role.adjunctEffect);target=potentials.Rows[index];target.Tag=new PotentialRecord{slot="부수",name=role.adjunct,activation="자동",trigger=adjunctTrigger,effect=adjunctEffect,raw=role.adjunctEffect};SetNameCell(target,"부수",role.adjunct,false);}else{target.Cells["disabled"].Value=false;target.Cells["name"].Value=role.adjunct;target.Cells["trigger"].Value=adjunctTrigger;target.Cells["effect"].Value=adjunctEffect;target.Cells["raw"].Value=role.adjunctEffect;var record=target.Tag as PotentialRecord??new PotentialRecord();record.activation="자동";record.uses="";record.targetType="";target.Tag=record;}}
  void NewProject(){if(!DiscardOkay())return;project=new EditorProject();project.trainers.Add(new TrainerRecord());project.pokemon.Add(new PokemonRecord());path="";dirty=false;RefreshTree(project.trainers[0]);}
  void RefreshTree(object select){loading=true;tree.Nodes.Clear();var trainers=tree.Nodes.Add("트레이너");foreach(var x in project.trainers){var n=trainers.Nodes.Add(x.name.Length>0?x.name:"(이름 없음)");n.Tag=x;}var mons=tree.Nodes.Add("포켓몬");foreach(var x in project.pokemon){var n=mons.Nodes.Add(x.name.Length>0?x.name:"(이름 없음)");n.Tag=x;}trainers.Expand();mons.Expand();tree.SelectedNode=tree.Nodes.Cast<TreeNode>().SelectMany(n=>n.Nodes.Cast<TreeNode>()).FirstOrDefault(n=>Object.ReferenceEquals(n.Tag,select));loading=false;LoadCurrent();UpdateTitle();}
  void AddTrainer(){SaveCurrent();var x=new TrainerRecord();project.trainers.Add(x);dirty=true;RefreshTree(x);}void AddPokemon(){SaveCurrent();var x=new PokemonRecord();project.pokemon.Add(x);dirty=true;RefreshTree(x);}
  void DeleteCurrent(){var x=Current;if(x==null)return;if(MessageBox.Show(this,"선택 데이터를 삭제할까요?","삭제",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;if(x is TrainerRecord)project.trainers.Remove((TrainerRecord)x);else project.pokemon.Remove((PokemonRecord)x);dirty=true;RefreshTree(project.trainers.Cast<object>().Concat(project.pokemon).FirstOrDefault());}
  void LoadCurrent(){if(loading)return;loading=true;var trainer=Current as TrainerRecord;var pokemon=Current as PokemonRecord;tabs.TabPages[0].Enabled=trainer!=null;tabs.TabPages[1].Enabled=pokemon!=null;if(trainer!=null){tName.Text=trainer.name;tOrigin.Text=trainer.origin;var a=new[]{trainer.command,trainer.training,trainer.leadership,trainer.ability};for(int i=0;i<4;i++){aptRank[i].Text=a[i].rank;aptDesc[i].Text=a[i].description;}FillPotentials(trainer.potentials);selectionLabel.Text="트레이너 · "+(trainer.name.Length>0?trainer.name:"이름 없음");tabs.SelectedIndex=0;}else if(pokemon!=null){pName.Text=pokemon.name;pTypes.Text=string.Join(", ",pokemon.types);pAbility.Text=pokemon.ability;pModel.Text=pokemon.model;pLevel.Value=Math.Max(pLevel.Minimum,Math.Min(pLevel.Maximum,pokemon.level));pItem.Text=pokemon.item;pMoves.Text=string.Join("\r\n",pokemon.moves);aa.Text=pokemon.asciiArt;int[] v={pokemon.stats.hp,pokemon.stats.attack,pokemon.stats.defense,pokemon.stats.spAttack,pokemon.stats.spDefense,pokemon.stats.speed};for(int i=0;i<6;i++)stats[i].Value=Math.Min(stats[i].Maximum,v[i]);FillPotentials(pokemon.potentials);selectionLabel.Text="포켓몬 · "+(pokemon.name.Length>0?pokemon.name:"이름 없음");tabs.SelectedIndex=1;}else{potentials.Rows.Clear();selectionLabel.Text="왼쪽에서 데이터를 선택하세요.";}loading=false;UpdateStatPreview();}
  List<PotentialRecord> CurrentPotentials(){var t=Current as TrainerRecord;if(t!=null)return t.potentials;var p=Current as PokemonRecord;return p==null?null:p.potentials;}
  void FillPotentials(List<PotentialRecord> list){potentials.Rows.Clear();var column=(DataGridViewComboBoxColumn)potentials.Columns["slot"];column.Items.Clear();column.Items.Add("");var allowed=Current is TrainerRecord?EditorTemplate.TrainerSlotNames:Current is PokemonRecord?EditorTemplate.PokemonSlotNames:EditorTemplate.TrainerSlotNames.Concat(EditorTemplate.PokemonSlotNames);foreach(string slot in allowed.Concat(list.Select(x=>x.slot)).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct())column.Items.Add(slot);foreach(var p in list){if(string.IsNullOrWhiteSpace(p.trigger)&&!string.IsNullOrWhiteSpace(p.effect)){string condition,result;PotentialLibrary.Split(p.effect,out condition,out result);if(condition.Length>0){if(p.raw.Length==0)p.raw=p.effect;p.trigger=condition;p.effect=result;}}int index=potentials.Rows.Add(!p.enabled,p.slot,p.name,p.trigger,p.effect,p.raw);var row=potentials.Rows[index];row.Tag=p;SetNameCell(row,p.slot,p.name,true);}}
  string Cell(DataGridViewRow r,string name){var v=r.Cells[name].Value;return v==null?"":v.ToString().Trim();}
  void SaveCurrent(){if(loading||Current==null)return;var trainer=Current as TrainerRecord;var pokemon=Current as PokemonRecord;if(trainer!=null){trainer.name=tName.Text.Trim();trainer.origin=tOrigin.Text.Trim();var a=new[]{trainer.command,trainer.training,trainer.leadership,trainer.ability};for(int i=0;i<4;i++){a[i].rank=aptRank[i].Text.Trim();a[i].description=aptDesc[i].Text.Trim();}}else if(pokemon!=null){pokemon.name=pName.Text.Trim();pokemon.types=pTypes.Text.Split(new[]{',','/','\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x.Length>0).ToList();pokemon.ability=pAbility.Text.Trim();pokemon.model=pModel.Text.Trim();pokemon.level=(int)pLevel.Value;pokemon.item=pItem.Text.Trim();pokemon.moves=pMoves.Lines.Select(x=>x.Trim()).Where(x=>x.Length>0).ToList();pokemon.asciiArt=aa.Text;pokemon.stats.hp=(int)stats[0].Value;pokemon.stats.attack=(int)stats[1].Value;pokemon.stats.defense=(int)stats[2].Value;pokemon.stats.spAttack=(int)stats[3].Value;pokemon.stats.spDefense=(int)stats[4].Value;pokemon.stats.speed=(int)stats[5].Value;}var list=CurrentPotentials();if(list!=null){list.Clear();foreach(DataGridViewRow row in potentials.Rows)if(!row.IsNewRow&&(Cell(row,"name").Length>0||Cell(row,"slot").Length>0)){var disabled=row.Cells["disabled"].Value;var old=row.Tag as PotentialRecord??new PotentialRecord();list.Add(new PotentialRecord{enabled=disabled==null||!Convert.ToBoolean(disabled),slot=Cell(row,"slot"),targetType="",name=Cell(row,"name"),activation=old.activation,uses=old.uses,trigger=Cell(row,"trigger"),effect=Cell(row,"effect"),raw=Cell(row,"raw")});}}if(tree.SelectedNode!=null)tree.SelectedNode.Text=trainer!=null?(trainer.name.Length>0?trainer.name:"(이름 없음)"):(pokemon.name.Length>0?pokemon.name:"(이름 없음)");}
  void UpdateStatPreview(){var p=Current as PokemonRecord;if(statPreview==null||p==null){if(statPreview!=null)statPreview.Text="";return;}int[] value=EditorBridge.PreviewStats(p);statPreview.Text="동레벨 · IV31 / EV0 / 중립:  "+string.Join(" / ",value);}
  void SendCurrent(int side){SaveCurrent();var p=Current as PokemonRecord;if(p==null||sendToBattle==null)return;try{sendToBattle(p,side);}catch(Exception ex){MessageBox.Show(this,ex.Message,"배틀 슬롯 적용 실패");}}
  void SendCurrentTrainer(int side){SaveCurrent();var t=Current as TrainerRecord;if(t==null||sendTrainerToBattle==null)return;try{sendTrainerToBattle(t,side);}catch(Exception ex){MessageBox.Show(this,ex.Message,"트레이너 적용 실패");}}
  void AddPotential(PotentialRecord p){var list=CurrentPotentials();if(list==null){MessageBox.Show(this,"트레이너 또는 포켓몬을 먼저 선택하세요.");return;}SaveCurrent();list.Add(p);loading=true;FillPotentials(list);loading=false;tabs.SelectedIndex=2;dirty=true;UpdateTitle();}
  void AddPokemonSlots(){var list=CurrentPotentials();if(!(Current is PokemonRecord)){MessageBox.Show(this,"포켓몬을 선택한 뒤 사용하세요.");return;}SaveCurrent();foreach(var p in EditorTemplate.PokemonSlots())if(!list.Any(x=>x.slot==p.slot))list.Add(p);loading=true;FillPotentials(list);loading=false;dirty=true;tabs.SelectedIndex=2;UpdateTitle();}
  void AddOrders(bool deploy){if(!(Current is TrainerRecord)){MessageBox.Show(this,"트레이너를 선택한 뒤 사용하세요.");return;}SaveCurrent();var list=CurrentPotentials();foreach(var p in EditorTemplate.Orders(deploy))if(!list.Any(x=>x.name==p.name))list.Add(p);loading=true;FillPotentials(list);loading=false;dirty=true;tabs.SelectedIndex=2;UpdateTitle();}
  void AddAimOrders(){if(!(Current is TrainerRecord)){MessageBox.Show(this,"트레이너를 선택한 뒤 사용하세요.");return;}SaveCurrent();var list=CurrentPotentials();bool deploy=list.Any(x=>x.name.StartsWith("전개 "));foreach(var p in EditorTemplate.ExtendedOrders(deploy))if(!list.Any(x=>x.name==p.name))list.Add(p);loading=true;FillPotentials(list);loading=false;dirty=true;tabs.SelectedIndex=2;UpdateTitle();}
  void PastePotentials(){if(!Clipboard.ContainsText()){MessageBox.Show(this,"클립보드에 텍스트가 없습니다.");return;}string slot=Current is TrainerRecord?"고유":"종족 ①";int added=0;foreach(string line in Clipboard.GetText().Replace("\r","").Split('\n'))if(line.Contains("『")&&line.Contains("』")){var p=EditorTemplate.Parse(line,slot);if(p.name.Length>0){AddPotential(p);added++;}}if(added==0)MessageBox.Show(this,"『이름』… 효과 형식의 줄을 찾지 못했습니다.");}
  void DeletePotential(){if(potentials.SelectedRows.Count==0)return;foreach(DataGridViewRow row in potentials.SelectedRows)if(!row.IsNewRow)potentials.Rows.Remove(row);GridChanged();}
  string Json(){SaveCurrent();return new JavaScriptSerializer{MaxJsonLength=50000000}.Serialize(project);}
  void Open(){if(!DiscardOkay())return;var d=new OpenFileDialog{Filter="AA Battle 데이터 (*.aabdata.json)|*.aabdata.json|JSON (*.json)|*.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;try{project=new JavaScriptSerializer{MaxJsonLength=50000000}.Deserialize<EditorProject>(File.ReadAllText(d.FileName,Encoding.UTF8));if(project.trainers==null)project.trainers=new List<TrainerRecord>();if(project.pokemon==null)project.pokemon=new List<PokemonRecord>();path=d.FileName;dirty=false;RefreshTree(project.trainers.Cast<object>().Concat(project.pokemon).FirstOrDefault());}catch(Exception ex){MessageBox.Show(this,"파일을 열 수 없습니다.\r\n"+ex.Message,"열기 오류");}}
  void Save(){if(path.Length==0){SaveAs();return;}try{File.WriteAllText(path,Pretty(Json()),new UTF8Encoding(true));dirty=false;UpdateTitle();}catch(Exception ex){MessageBox.Show(this,ex.Message,"저장 오류");}}
  void SaveAs(){var d=new SaveFileDialog{Filter="AA Battle 데이터 (*.aabdata.json)|*.aabdata.json",FileName="battle-data.aabdata.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;path=d.FileName;Save();}
  static string Pretty(string json){var sb=new StringBuilder();bool quoted=false,escape=false;int indent=0;foreach(char c in json){if(quoted){sb.Append(c);if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='\"')quoted=false;continue;}if(c=='\"'){quoted=true;sb.Append(c);}else if(c=='{'||c=='['){sb.Append(c).AppendLine();indent++;sb.Append(new string(' ',indent*2));}else if(c=='}'||c==']'){sb.AppendLine();indent--;sb.Append(new string(' ',indent*2)).Append(c);}else if(c==','){sb.Append(c).AppendLine().Append(new string(' ',indent*2));}else if(c==':')sb.Append(": ");else if(!Char.IsWhiteSpace(c))sb.Append(c);}return sb.ToString();}
  bool DiscardOkay(){return !dirty||MessageBox.Show(this,"저장하지 않은 변경을 버릴까요?","변경 사항",MessageBoxButtons.YesNo)==DialogResult.Yes;}
  void UpdateTitle(){fileLabel.Text=(path.Length>0?Path.GetFileName(path):"새 데이터")+(dirty?" ＊":"");}
  void RefreshPreview(){SaveCurrent();preview.Text=Current is TrainerRecord?TrainerText((TrainerRecord)Current):Current is PokemonRecord?PokemonText((PokemonRecord)Current):"왼쪽에서 데이터를 선택하세요.";}
  static string PotentialText(IEnumerable<PotentialRecord> list){var sb=new StringBuilder();foreach(var p in list.Where(x=>x.enabled)){sb.Append("『").Append(p.name).Append("』…　");if(p.uses.Length>0)sb.Append(p.uses).Append('/');if(p.activation.Length>0)sb.Append(p.activation).Append('/');if(p.trigger.Length>0)sb.Append(p.trigger).Append("、");sb.AppendLine(p.effect.Length>0?p.effect:p.raw);}return sb.ToString();}
  static string TrainerText(TrainerRecord t){var a=new[]{t.command,t.training,t.leadership,t.ability};string[] n={"지시","육성","통솔","능력"};var sb=new StringBuilder("───────────────────────────────────────────────────\r\n【이름】 ").AppendLine(t.name).Append("【출신】 ").AppendLine(t.origin).AppendLine("\r\n【자질 평가】");for(int i=0;i<4;i++)sb.Append("ㆍ").Append(n[i]).Append("：「").Append(a[i].rank).Append("」　…　").AppendLine(a[i].description);sb.AppendLine("\r\n【지령 포텐셜】").Append(PotentialText(t.potentials.Where(x=>x.slot=="지령"))).AppendLine("\r\n【고유 포텐셜】").Append(PotentialText(t.potentials.Where(x=>x.slot!="지령"&&x.slot!="전용"))).AppendLine("\r\n【전용 포텐셜】").Append(PotentialText(t.potentials.Where(x=>x.slot=="전용")));return sb.ToString();}
  static string PokemonText(PokemonRecord p){var s=p.stats;return new StringBuilder("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\r\n【이름】 ").AppendLine(p.name).Append("【타입】 ").AppendLine(string.Join(" / ",p.types)).Append("【특성】 ").AppendLine(p.ability).Append("【모델】 《").Append(p.model).AppendLine("》").Append("【레벨】 ").AppendLine(p.level.ToString()).Append("【소지품】 ").AppendLine(p.item).Append("\r\n【기술 × ").Append(p.moves.Count).Append(" : ").Append(string.Join(", ",p.moves)).AppendLine("】\r\n").Append("체력 : ").AppendLine(s.hp.ToString()).Append("공격 : ").AppendLine(s.attack.ToString()).Append("방어 : ").AppendLine(s.defense.ToString()).Append("특공 : ").AppendLine(s.spAttack.ToString()).Append("특방 : ").AppendLine(s.spDefense.ToString()).Append("속도 : ").AppendLine(s.speed.ToString()).Append("총합 : ").AppendLine(s.Total().ToString()).AppendLine("\r\n○종족치 랭크 견본\r\nS…200~ / AAA…170~195 / AA…140~165 / A…110~135\r\nB…90~105 / C…60~85 / D…40~55 / E…1~35\r\n예: A+=135, A=111~134, A-=110 (각 랭크 ++ 상한은 제공 양식 참조)\r\n").AppendLine("【포텐셜】").Append(PotentialText(p.potentials)).ToString();}
  protected override void OnFormClosing(FormClosingEventArgs e){if(!allowClose&&!DiscardOkay())e.Cancel=true;base.OnFormClosing(e);}
  public void Sample(){var t=project.trainers[0];t.name="테스트 트레이너";t.origin="참치 지방";t.command.rank="B";t.potentials=EditorTemplate.Orders(false);var p=project.pokemon[0];p.name="테스트몬";p.types.AddRange(new[]{"전기","강철"});p.ability="부유";p.model="샘플";p.level=200;p.moves.AddRange(new[]{"10만볼트","방어","비바라기","볼트체인지"});p.stats=new StatsRecord{hp=100,attack=80,defense=100,spAttack=130,spDefense=100,speed=90};p.potentials=EditorTemplate.PokemonSlots();var role=EditorTemplate.Role("탐사대장");p.potentials[0].name=role.name;p.potentials[0].activation="자동";p.potentials[0].effect=role.effect;p.potentials[15].name=role.adjunct;p.potentials[15].activation="자동";p.potentials[15].effect=role.adjunctEffect;var initiative=EditorTemplate.FixedOption("선","선의 선");p.potentials[10].name=initiative.name;p.potentials[10].activation="자동";p.potentials[10].effect=initiative.effect;var common=EditorTemplate.FixedOption("범용","기합");p.potentials[14].name=common.name;p.potentials[14].activation="자동";p.potentials[14].effect=common.effect;p.potentials[4].name="샘플의 전도";p.potentials[4].trigger="전기 기술이 명중했을 때";p.potentials[4].effect="상대의 특방을 1랭크 내린다.";RefreshTree(p);tabs.SelectedIndex=2;}
  public void SelectTabForTest(int index){tabs.SelectedIndex=index;if(index==3)RefreshPreview();Application.DoEvents();}
  public void CloseForTest(){allowClose=true;Close();}
 }

 static class DataEditorProgram {
  static void Check(bool ok,string label){if(!ok)throw new Exception("Data editor FAIL: "+label);}
  static void Capture(Form form,string path){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
  [STAThread]public static int Main(string[] args){try{if(args.Length>1&&args[0]=="--export-components"){PotentialParts.Export(args[1]);return 0;}if(args.Length>0&&args[0]=="--self-test"){var p=new EditorProject();var t=new TrainerRecord{name="T"};t.potentials=EditorTemplate.Orders(false);p.trainers.Add(t);var mon=new PokemonRecord{name="P"};mon.potentials=EditorTemplate.PokemonSlots();p.pokemon.Add(mon);var j=new JavaScriptSerializer().Serialize(p);var q=new JavaScriptSerializer().Deserialize<EditorProject>(j);var parsed=EditorTemplate.Parse("『시험』… 1/시/선행/상대가 교대할 때, 자신의 속도를 올린다.","종족 ①");Check(q.trainers.Count==1&&q.pokemon.Count==1,"roundtrip");Check(t.potentials.Count==10,"base four and six orders");Check(EditorTemplate.TrainerSlotNames.SequenceEqual(new[]{"고유","전용","지령"}),"trainer potential type choices");Check(mon.potentials.Count==19&&EditorTemplate.PokemonSlotNames.Length==19&&mon.potentials[3].slot=="이명"&&mon.potentials[18].slot=="PT ②","pokemon potential type choices");Check(EditorTemplate.RolePotentials.Length==42&&EditorTemplate.Role("에이스")!=null&&EditorTemplate.Role("에이스").effect.Contains("1.33배"),"fixed role potential choices");Check(EditorTemplate.Role("탐사대원").adjunct=="프라이멀 헌트"&&EditorTemplate.Role("탐사대장").adjunct=="프라이멀 헌트"&&EditorTemplate.Role("조사대원").adjunct=="리서치 헌트","Abaddon role adjunct mapping");Check(EditorTemplate.CommonPotentials.Length==6&&EditorTemplate.FixedOption("범용","군략").effect.Contains("1.2배"),"fixed common potential choices");Check(EditorTemplate.InitiativePotentials.Length==4&&EditorTemplate.FixedOption("선","삼종의 신기").effect.Contains("육성：AA"),"fixed initiative potential choices");Check(EditorTemplate.CounterTypeNames().Length==17&&EditorTemplate.CounterOptions("회피","불꽃").First().name=="대화회피"&&EditorTemplate.CounterOptions("격","드래곤").Length==8&&EditorTemplate.CounterOption("격","드래곤","극룡반격").effect.Contains("중확률"),"typed counter potential choices");Check(EditorTemplate.InferCounterType("대염내성")=="에스퍼"&&EditorTemplate.PotentialTriggerCatalog.Length>=18&&EditorTemplate.PotentialEffectCatalog().Length>200,"potential catalogs");Check(EditorTemplate.ExtendedOrders(false).Count==3,"optional aim, evasion and sure-hit directives");Check(parsed.name=="시험"&&parsed.uses.Length>0&&parsed.activation=="선행"&&parsed.trigger.Length>0&&parsed.effect.Length>0,"potential split");CatalogTests.Run();File.WriteAllText(args.Length>1?args[1]:"data-editor-test.txt","PASS: project roundtrip, trainer directives, selectable 19 pokemon potential types, 42 roles, 6 common potentials, 4 initiative potentials, typed counters, move/trigger/effect catalogs, Abaddon role adjuncts, trigger/effect parser, 4151 embedded research definitions, provenance, condition splitting and optional wording preservation.");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Fonts.Load();var form=new DataEditorForm();if(args.Length>1&&args[0]=="--render-preview"){form.Shown+=(s,e)=>{form.Sample();form.TestCatalogUi();form.SelectTabForTest(2);Capture(form,args[1]);form.SelectTabForTest(1);Capture(form,args[1]+".pokemon.png");form.SelectTabForTest(3);Capture(form,args[1]+".sheet.png");form.SelectTabForTest(4);Capture(form,args[1]+".moves.png");form.SelectTabForTest(5);Capture(form,args[1]+".potentials.png");form.CloseForTest();};}Application.Run(form);return 0;}catch(Exception ex){if(args.Length>0){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data-editor-error.txt"),ex.ToString());return 1;}MessageBox.Show(ex.Message,"데이터 편집기 오류");return 1;}}
 }
